#!/usr/bin/env node
// CLI for Agent Browser Bridge. Works without any agent framework: anything that
// can run a shell command can drive Chrome through it.
//
//   abb status
//   abb doctor
//   abb selftest
//   abb extension
//   abb group_begin '{"title":"research"}'
//   abb click '{"selector":"#submit"}'
//   abb text '{"limit":4000}'

import http from 'node:http';
import process from 'node:process';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { callHub, hubStatus } from '../lib/client.mjs';
import { DEFAULT_PORT } from '../lib/hub.mjs';
import { TOOLS } from '../lib/tools.mjs';

const PORT = Number(process.env.ABB_PORT || DEFAULT_PORT);
const CLIENT_ID = process.env.ABB_CLIENT_ID || 'default';
const VERSION = '1.0.0';

const pkgRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const extensionDir = path.join(pkgRoot, 'extension');

const ALIASES = Object.fromEntries(TOOLS.filter((t) => t.action).map((t) => [t.name.replace(/^browser_/, ''), t.action]));

function usage() {
  console.log(`agent-browser-bridge ${VERSION}

Usage:
  abb <tool> [json-args]
  abb status | doctor | selftest | extension | --version

Tools:
  ${TOOLS.map((t) => t.name.replace(/^browser_/, '')).join(', ')}

Examples:
  abb group_begin '{"title":"pricing research","url":"https://example.com"}'
  abb snapshot
  abb click '{"selector":"#buy"}'
  abb type '{"selector":"#email","text":"me@example.com"}'
  abb screenshot '{"fullPage":true}' > shot.json
  abb group_end

Env:
  ABB_PORT=${PORT}   ABB_CLIENT_ID=${CLIENT_ID}`);
}

async function send(action, args = {}) {
  return callHub(action, { ...args, clientId: CLIENT_ID }, { port: PORT });
}

function parseArgs(raw) {
  if (!raw) return {};
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

function print(out) {
  if (out && typeof out === 'object' && out.image) {
    console.log(JSON.stringify({ image: `[base64 png, ${out.image.length} chars]` }, null, 2));
    return;
  }
  console.log(typeof out === 'string' ? out : JSON.stringify(out, null, 2));
}

async function cmdStatus() {
  const st = await hubStatus({ port: PORT });
  let ext = null;
  if (st.connected) {
    try {
      ext = await send('hello');
    } catch (e) {
      ext = { error: String(e && e.message || e) };
    }
  }
  console.log(JSON.stringify({ ...st, port: PORT, clientId: CLIENT_ID, extension: ext }, null, 2));
}

async function cmdDoctor() {
  const lines = [];
  const ok = (m) => lines.push(`  ok    ${m}`);
  const bad = (m) => lines.push(`  FAIL  ${m}`);
  const warn = (m) => lines.push(`  warn  ${m}`);

  const major = Number(process.versions.node.split('.')[0]);
  if (major >= 18) ok(`node ${process.version}`);
  else bad(`node ${process.version} — need >= 18 for fetch`);

  const st = await hubStatus({ port: PORT });
  if (!st.listening) bad(`no bridge server on port ${PORT} (start your agent, which spawns it, or run: node bin/mcp-server.mjs)`);
  else if (!st.connected) bad(`server is up on port ${PORT}, but no extension is polling it`);
  else {
    ok(`server on port ${PORT}, extension connected`);
    try {
      const hello = await send('hello');
      ok(`extension v${hello.version}`);
    } catch (e) {
      warn(`extension did not answer hello: ${e.message}`);
    }
  }

  lines.push('');
  lines.push(`  extension source: ${extensionDir}`);
  lines.push('  if it is not loaded: chrome://extensions → Developer mode → Load unpacked → pick that folder');
  lines.push('  after editing extension files, click the reload arrow on its card (Chrome does not auto-reload unpacked extensions)');
  console.log(lines.join('\n'));
}

async function cmdExtension() {
  console.log(extensionDir);
  console.log('');
  console.log('Load it once per Chrome profile:');
  console.log('  1. open chrome://extensions');
  console.log('  2. turn on Developer mode (top right)');
  console.log('  3. Load unpacked → select the folder above');
  console.log('  4. after any edit inside that folder, click the reload arrow on the card');
}

async function cmdSelftest() {
  const results = [];
  const step = async (name, fn) => {
    try {
      const detail = await fn();
      results.push({ name, ok: true, detail });
      console.log(`  PASS  ${name}${detail ? ` — ${detail}` : ''}`);
    } catch (e) {
      results.push({ name, ok: false, detail: String(e && e.message || e) });
      console.log(`  FAIL  ${name} — ${e && e.message}`);
    }
  };

  const page = `<!doctype html><meta charset="utf-8"><title>ABB Selftest</title>
<body style="font:16px system-ui;padding:40px">
<h1 id="head">ABB SELFTEST</h1>
<input id="box" placeholder="type here" style="font-size:16px;padding:6px">
<button id="go" style="font-size:16px;padding:6px 14px">Run</button>
<p id="out">idle</p>
<script>document.getElementById('go').onclick=()=>{document.getElementById('out').textContent='clicked';};</script>
</body>`;

  const httpServer = http.createServer((req, res) => {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(page);
  });
  const port = await new Promise((resolve) => httpServer.listen(0, '127.0.0.1', () => resolve(httpServer.address().port)));
  const url = `http://127.0.0.1:${port}/`;

  console.log('Running self-test against your live Chrome…');
  await step('extension handshake', async () => {
    const hello = await send('hello');
    return `v${hello.version}`;
  });
  await step('start task group', async () => {
    const g = await send('group_begin', { title: 'abb selftest', url });
    if (!g.groupId) throw new Error('no group id returned');
    return `group ${g.groupId}`;
  });
  await step('read page text', async () => {
    const text = await send('text');
    if (!String(text).includes('ABB SELFTEST')) throw new Error('unexpected page text');
    return 'title found';
  });
  await step('click button', async () => {
    await send('click', { selector: '#go' });
    const text = await send('text');
    if (!String(text).includes('clicked')) throw new Error('click had no effect');
    return 'state changed';
  });
  await step('type into input', async () => {
    await send('type', { selector: '#box', text: 'hello bridge' });
    const value = await send('eval', { expression: 'document.getElementById("box").value' });
    if (value !== 'hello bridge') throw new Error(`value was ${JSON.stringify(value)}`);
    return 'value set';
  });
  await step('accessibility snapshot', async () => {
    const snap = await send('snapshot');
    if (!String(snap).includes('button')) throw new Error('no button in AX tree');
    return `${String(snap).split('\n').length} lines`;
  });
  await step('screenshot', async () => {
    const shot = await send('screenshot');
    if (!shot || !shot.image) throw new Error('no image returned');
    return `${Math.round(shot.image.length / 1024)} KB base64`;
  });
  await step('tabs inside task group', async () => {
    const tabs = await send('tabs', { groupOnly: true });
    if (!Array.isArray(tabs) || tabs.length === 0) throw new Error('task group is empty');
    return `${tabs.length} tab(s)`;
  });
  await step('finish task group', async () => {
    await send('group_end');
    return 'pointer cleared';
  });

  httpServer.close();

  const failed = results.filter((r) => !r.ok).length;
  console.log('');
  console.log(failed === 0 ? `ALL ${results.length} CHECKS PASSED` : `${failed} of ${results.length} CHECKS FAILED`);
  process.exit(failed === 0 ? 0 : 1);
}

const [cmd, ...rest] = process.argv.slice(2);

if (!cmd || cmd === '--help' || cmd === '-h') {
  usage();
  process.exit(0);
}
if (cmd === '--version') {
  console.log(VERSION);
  process.exit(0);
}

try {
  if (cmd === 'status') await cmdStatus();
  else if (cmd === 'doctor') await cmdDoctor();
  else if (cmd === 'extension') await cmdExtension();
  else if (cmd === 'selftest') await cmdSelftest();
  else {
    const action = ALIASES[cmd] || (TOOLS.find((t) => t.name === cmd)?.action) || (cmd === 'hello' ? 'hello' : null);
    if (!action) {
      console.error(`unknown command: ${cmd}\n`);
      usage();
      process.exit(2);
    }
    const args = parseArgs(rest.join(' '));
    if (args === null) {
      console.error('arguments must be JSON, e.g. \'{"selector":"#go"}\'');
      process.exit(2);
    }
    print(await send(action, args));
  }
} catch (e) {
  console.error('ERROR: ' + (e && e.message || e));
  process.exit(1);
}

#!/usr/bin/env node
// MCP stdio server for Agent Browser Bridge.
//
//   node bin/mcp-server.mjs
//
// The first instance owns the local bridge port. Later instances (other agents,
// other editor windows) detect the port is taken and forward commands to the
// running hub, so many agents can drive one Chrome at the same time.
//
// Env:
//   ABB_PORT        bridge port (default 9333; must match the extension option)
//   ABB_CLIENT_ID   task-group namespace for this agent (default "default")
//   ABB_QUIET=1     silence stderr notes

import readline from 'node:readline';
import process from 'node:process';
import { createHub, DEFAULT_PORT } from '../lib/hub.mjs';
import { callHub, hubStatus } from '../lib/client.mjs';
import { TOOLS, ACTION_BY_TOOL } from '../lib/tools.mjs';

const PORT = Number(process.env.ABB_PORT || DEFAULT_PORT);
const CLIENT_ID = process.env.ABB_CLIENT_ID || 'default';
const QUIET = process.env.ABB_QUIET === '1';

const log = (...a) => { if (!QUIET) console.error('[agent-browser]', ...a); };

let hub = null;
let mode = 'hub';

async function start() {
  const candidate = createHub({ port: PORT });
  try {
    await candidate.listen();
    hub = candidate;
    mode = 'hub';
    log(`hub listening on 127.0.0.1:${PORT} (client "${CLIENT_ID}")`);
  } catch (e) {
    if (e && e.code === 'EADDRINUSE') {
      mode = 'client';
      log(`port ${PORT} already owned by another bridge; forwarding as client "${CLIENT_ID}"`);
    } else {
      throw e;
    }
  }
}

async function send(action, args = {}) {
  const payload = { ...args, clientId: CLIENT_ID };
  if (mode === 'hub') return hub.enqueue(action, payload);
  return callHub(action, payload, { port: PORT });
}

async function status() {
  const base = mode === 'hub' ? hub.status() : await hubStatus({ port: PORT });
  let ext = null;
  if (base.connected) {
    try {
      ext = await send('hello');
    } catch (e) {
      ext = { error: String(e && e.message || e) };
    }
  }
  return { ...base, mode, clientId: CLIENT_ID, port: PORT, extension: ext };
}

async function waitForExtension(timeoutMs = 5000) {
  const started = Date.now();
  for (;;) {
    const s = mode === 'hub' ? hub.status() : await hubStatus({ port: PORT });
    if (s.connected) return true;
    if (Date.now() - started > timeoutMs) return false;
    await new Promise((r) => setTimeout(r, 250));
  }
}

function reply(id, result) {
  process.stdout.write(JSON.stringify({ jsonrpc: '2.0', id, result }) + '\n');
}

function replyError(id, message) {
  process.stdout.write(JSON.stringify({ jsonrpc: '2.0', id, result: { content: [{ type: 'text', text: `ERROR: ${message}` }], isError: true } }) + '\n');
}

async function callTool(name, args) {
  if (name === 'browser_status') return status();

  const action = ACTION_BY_TOOL[name];
  if (!action) throw new Error(`unknown tool: ${name}`);

  if (!(await waitForExtension())) {
    const where = mode === 'hub' ? `port ${PORT}` : `the bridge on port ${PORT}`;
    throw new Error(
      `Chrome extension is not connected to ${where}. ` +
        `Load the extension/ folder at chrome://extensions (Developer mode → Load unpacked), ` +
        `then click reload on its card.`,
    );
  }
  return send(action, args || {});
}

const rl = readline.createInterface({ input: process.stdin });

rl.on('line', async (line) => {
  if (!line.trim()) return;
  let msg;
  try {
    msg = JSON.parse(line);
  } catch {
    return;
  }

  if (msg.method === 'initialize') {
    reply(msg.id, {
      protocolVersion: '2024-11-05',
      capabilities: { tools: {} },
      serverInfo: { name: 'agent-browser-bridge', version: '1.0.0' },
    });
    return;
  }
  if (msg.method === 'notifications/initialized') return;
  if (msg.method === 'ping') return reply(msg.id, {});

  if (msg.method === 'tools/list') {
    const tools = TOOLS.map(({ action, ...rest }) => rest);
    return reply(msg.id, { tools });
  }

  if (msg.method === 'tools/call') {
    const { name, arguments: args } = msg.params || {};
    try {
      const out = await callTool(name, args || {});
      let content;
      if (out && typeof out === 'object' && out.image) {
        content = [
          { type: 'text', text: 'screenshot captured' },
          { type: 'image', data: out.image, mimeType: 'image/png' },
        ];
      } else {
        content = [{ type: 'text', text: typeof out === 'string' ? out : JSON.stringify(out, null, 2) }];
      }
      reply(msg.id, { content });
    } catch (e) {
      replyError(msg.id, String((e && e.message) || e));
    }
    return;
  }

  if (msg.id != null) {
    process.stdout.write(JSON.stringify({ jsonrpc: '2.0', id: msg.id, error: { code: -32601, message: 'method not found' } }) + '\n');
  }
});

start().then(
  () => log('ready'),
  (e) => {
    log('failed to start:', e && e.message);
    process.exit(1);
  },
);
